package com.aoo.bcg.common.transaction;import java.time.Duration;import java.util.Objects;
/** Explicit read-only, primary/replica and consistency contract for every repository operation. */
public final class ConsistencyRoutingPolicy{public enum Intent{AUTHORITATIVE_WRITE,STRONG_READ,EVENTUAL_READ}public enum Target{PRIMARY,REPLICA}public record Request(Intent intent,long minimumObservedVersion,Duration maximumStaleness){public Request{Objects.requireNonNull(intent);Objects.requireNonNull(maximumStaleness);if(minimumObservedVersion<0||maximumStaleness.isNegative())throw new IllegalArgumentException("invalid consistency request");}}public record Decision(Target target,boolean readOnly,String isolation,Duration maximumStaleness){}public Decision route(Request request,long replicaAppliedVersion){Objects.requireNonNull(request);return switch(request.intent()){case AUTHORITATIVE_WRITE->new Decision(Target.PRIMARY,false,"READ_COMMITTED",Duration.ZERO);case STRONG_READ->new Decision(Target.PRIMARY,true,"REPEATABLE_READ",Duration.ZERO);case EVENTUAL_READ->{boolean caughtUp=replicaAppliedVersion>=request.minimumObservedVersion();yield caughtUp?new Decision(Target.REPLICA,true,"READ_COMMITTED",request.maximumStaleness()):new Decision(Target.PRIMARY,true,"READ_COMMITTED",Duration.ZERO);}};}}
